const item = $input.first().json;
const { action, targetType, epics, epicId, storyId, taskId } = item;

let isValidTarget = true;
let preCheckError = '';
let targetMeta = {};

// Kiểm tra sự tồn tại của target ID tương ứng
if (action === 'ADD') {
  if (targetType === 'STORY') {
    let epicFound = null;
    if (epicId) {
      epicFound = epics.find(e => e.id === epicId);
    } else {
      epicFound = epics[0];
    }
    if (!epicFound) {
      isValidTarget = false;
      preCheckError = "Khong tim thay Epic cha voi ID '" + epicId + "' de them Story";
    } else {
      targetMeta = { targetEpicId: epicFound.id, epicTitle: epicFound.title };
    }
  } else if (targetType === 'TASK') {
    let storyFound = null;
    let parentEpicFound = null;
    for (const ep of epics) {
      const stories = ep.stories || ep.user_stories || [];
      const s = stories.find(st => st.id === storyId);
      if (s) {
        storyFound = s;
        parentEpicFound = ep;
        break;
      }
    }
    if (!storyFound) {
      isValidTarget = false;
      preCheckError = "Khong tim thay User Story voi ID '" + storyId + "' de them Task";
    } else {
      targetMeta = { targetStoryId: storyFound.id, targetEpicId: parentEpicFound.id, storyTitle: storyFound.title };
    }
  }
} else if (action === 'UPDATE' || action === 'DELETE') {
  if (targetType === 'STORY') {
    let storyFound = null;
    for (const ep of epics) {
      const stories = ep.stories || ep.user_stories || [];
      const s = stories.find(st => st.id === storyId);
      if (s) { storyFound = s; break; }
    }
    if (!storyFound) {
      isValidTarget = false;
      preCheckError = "Khong tim thay User Story voi ID '" + storyId + "' trong cay yeu cau";
    }
  } else if (targetType === 'TASK') {
    let taskFound = null;
    for (const ep of epics) {
      const stories = ep.stories || ep.user_stories || [];
      for (const st of stories) {
        const tasks = st.tasks || st.subtasks || [];
        const t = tasks.find(tk => tk.id === taskId);
        if (t) { taskFound = t; break; }
      }
      if (taskFound) break;
    }
    if (!taskFound) {
      isValidTarget = false;
      preCheckError = "Khong tim thay Task voi ID '" + taskId + "' trong cay yeu cau";
    }
  }
}

return [{
  json: {
    ...item,
    isValidTarget,
    preCheckError,
    targetMeta
  }
}];

const item = $input.first().json;
const { action, targetType, epicId, storyId, taskId, data } = item;
const rawEpics = item.epics || [];

// Tạo bản sao sâu (deep clone) để đảm bảo tính bất biến (immutable)
const newEpics = JSON.parse(JSON.stringify(rawEpics));
let message = '';
let affectedNodeId = null;

if (action === 'ADD') {
  if (targetType === 'STORY') {
    const targetEpic = epicId ? newEpics.find(e => e.id === epicId) : newEpics[0];
    const epicIdx = newEpics.indexOf(targetEpic);
    const newStoryId = 'epic-' + (epicIdx >= 0 ? epicIdx : 0) + '-story-' + Date.now();
    const newStory = {
      id: newStoryId,
      parentId: targetEpic.id,
      level: 2,
      type: 'Story',
      title: (data && data.title && data.title.trim()) ? data.title.trim() : 'User Story mới',
      description: (data && data.description) ? data.description.trim() : '',
      assigneeId: (data && data.assigneeId) || null,
      assigneeName: (data && data.assigneeName) || '',
      assigneeAvatar: (data && data.assigneeAvatar) || '',
      tasks: []
    };
    if (!targetEpic.stories) targetEpic.stories = [];
    targetEpic.stories.push(newStory);
    affectedNodeId = newStoryId;
    message = "Đã thêm User Story mới vào Epic '" + targetEpic.title + "' thành công";
  } else if (targetType === 'TASK') {
    let targetStory = null;
    for (const ep of newEpics) {
      const stories = ep.stories || [];
      const s = stories.find(st => st.id === storyId);
      if (s) { targetStory = s; break; }
    }
    const newTaskId = 'task-' + Date.now();
    const newTask = {
      id: newTaskId,
      parentId: targetStory.id,
      level: 3,
      type: 'Task',
      title: (data && data.title && data.title.trim()) ? data.title.trim() : 'Task mới',
      description: (data && data.description) ? data.description.trim() : '',
      assigneeId: (data && data.assigneeId) || null,
      assigneeName: (data && data.assigneeName) || '',
      assigneeAvatar: (data && data.assigneeAvatar) || ''
    };
    if (!targetStory.tasks) targetStory.tasks = [];
    targetStory.tasks.push(newTask);
    affectedNodeId = newTaskId;
    message = "Đã thêm Task mới vào Story '" + targetStory.title + "' thành công";
  }
} else if (action === 'UPDATE') {
  if (targetType === 'STORY') {
    for (const ep of newEpics) {
      const stories = ep.stories || [];
      const s = stories.find(st => st.id === storyId);
      if (s) {
        if (data.title !== undefined) s.title = String(data.title).trim();
        if (data.description !== undefined) s.description = String(data.description).trim();
        if (data.assigneeId !== undefined) s.assigneeId = data.assigneeId;
        if (data.assigneeName !== undefined) s.assigneeName = String(data.assigneeName).trim();
        if (data.assigneeAvatar !== undefined) s.assigneeAvatar = String(data.assigneeAvatar).trim();
        // BẢO TOÀN 100% mảng tasks con hiện có
        affectedNodeId = s.id;
        message = "Đã cập nhật User Story '" + s.title + "' thành công";
        break;
      }
    }
  } else if (targetType === 'TASK') {
    for (const ep of newEpics) {
      const stories = ep.stories || [];
      for (const st of stories) {
        const tasks = st.tasks || [];
        const t = tasks.find(tk => tk.id === taskId);
        if (t) {
          if (data.title !== undefined) t.title = String(data.title).trim();
          if (data.description !== undefined) t.description = String(data.description).trim();
          if (data.assigneeId !== undefined) t.assigneeId = data.assigneeId;
          if (data.assigneeName !== undefined) t.assigneeName = String(data.assigneeName).trim();
          if (data.assigneeAvatar !== undefined) t.assigneeAvatar = String(data.assigneeAvatar).trim();
          affectedNodeId = t.id;
          message = "Đã cập nhật Task '" + t.title + "' thành công";
          break;
        }
      }
      if (affectedNodeId) break;
    }
  }
} else if (action === 'DELETE') {
  if (targetType === 'STORY') {
    for (const ep of newEpics) {
      if (ep.stories) {
        const initialCount = ep.stories.length;
        ep.stories = ep.stories.filter(st => st.id !== storyId);
        if (ep.stories.length < initialCount) {
          affectedNodeId = storyId;
          message = "Đã xóa User Story và toàn bộ task con liên quan thành công";
          break;
        }
      }
    }
  } else if (targetType === 'TASK') {
    for (const ep of newEpics) {
      const stories = ep.stories || [];
      for (const st of stories) {
        if (st.tasks) {
          const initialCount = st.tasks.length;
          st.tasks = st.tasks.filter(tk => tk.id !== taskId);
          if (st.tasks.length < initialCount) {
            affectedNodeId = taskId;
            message = "Đã xóa Task thành công";
            break;
          }
        }
      }
      if (affectedNodeId) break;
    }
  }
}

return [{
  json: {
    ...item,
    epics: newEpics,
    treeData: newEpics,
    affectedNodeId,
    mutationSuccess: true,
    message
  }
}];

const item = $input.first().json;
const epics = item.treeData || item.epics || [];

let warnings = [];
let totalStoriesWithoutTasks = 0;

for (const ep of epics) {
  const stories = ep.stories || [];
  for (const st of stories) {
    const tasks = st.tasks || [];
    if (tasks.length === 0) {
      totalStoriesWithoutTasks++;
      warnings.push("Story '" + st.title + "' chưa có công việc kỹ thuật (Task) con.");
    }
  }
}

const healthScore = totalStoriesWithoutTasks === 0 ? 100 : Math.max(70, 100 - (totalStoriesWithoutTasks * 5));

return [{
  json: {
    ...item,
    healthAudit: {
      healthScore,
      warnings,
      totalWarnings: warnings.length
    }
  }
}];

const item = $input.first().json;
const epics = item.treeData || item.epics || [];

let totalStories = 0;
let totalTasks = 0;

for (const epic of epics) {
  const stories = epic.stories || [];
  totalStories += stories.length;
  for (const story of stories) {
    const tasks = story.tasks || [];
    totalTasks += tasks.length;
  }
}

const totalEpics = epics.length;
const totalNodes = totalEpics + totalStories + totalTasks;
const treeDepth = totalEpics > 0 ? (totalStories > 0 ? (totalTasks > 0 ? 3 : 2) : 1) : 0;
const avgTasksPerStory = totalStories > 0 ? parseFloat((totalTasks / totalStories).toFixed(1)) : 0;

return [{
  json: {
    ...item,
    kpiMetrics: {
      totalEpics,
      totalStories,
      totalTasks,
      totalNodes,
      treeDepth,
      avgTasksPerStory
    }
  }
}];

const item = $input.first().json;
const epics = item.treeData || item.epics || [];
const expandedNodesMap = {};

for (const epic of epics) {
  expandedNodesMap[epic.id] = true;
  const stories = epic.stories || [];
  for (const story of stories) {
    expandedNodesMap[story.id] = true;
  }
}

// Nếu có node bị tác động (thêm mới), tự động mở rộng node đó
if (item.affectedNodeId) {
  expandedNodesMap[item.affectedNodeId] = true;
}

return [{
  json: {
    ...item,
    uiConfig: {
      expandedNodesMap,
      viewportTargetId: item.affectedNodeId || null
    }
  }
}];
